package com.valorantx.business.service;
import com.valorantx.business.validation.UsuarioValidation; import com.valorantx.data.entity.Usuario; import com.valorantx.data.repository.UsuarioRepository; import com.valorantx.presentation.dto.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service;
@Service public class UsuarioServiceImpl implements UsuarioService { private final UsuarioRepository repository; private final UsuarioValidation validation; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); public UsuarioServiceImpl(UsuarioRepository r,UsuarioValidation v){repository=r;validation=v;} public String registrar(RegistroRequest r){validation.validarRegistro(r.nombreUsuario(),r.correo()); Usuario u=new Usuario();u.setNombreUsuario(r.nombreUsuario());u.setCorreo(r.correo());u.setContrasena(encoder.encode(r.contrasena()));repository.save(u);return "Usuario registrado correctamente";} public boolean iniciarSesion(LoginRequest r){return repository.findByNombreUsuario(r.nombreUsuario()).map(u->encoder.matches(r.contrasena(),u.getContrasena())).orElse(false);} }
